                "sampleValue": "10:00"
              }
            }
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_earphone.png",
      "description": "耳机图标素材，适合用于耳机歌单卡片的设备识别和轻量音乐场景提示。"
    }
  ]
}

